import { Component } from 'react'
import PropTypes from 'prop-types'
import { CollapsableBodyStyle, CollapsableHeader } from './index.style'
import { Row } from '../../commonStyle/index.style'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import isEmpty from 'lodash/isEmpty'
import Button from '../Button'

class Collapsible extends Component {
  static propTypes = {
    isOpen: PropTypes.bool,
    isAccordion: PropTypes.bool,
    header: PropTypes.string,
    className: PropTypes.string,
    titleClassName: PropTypes.string,
    isHideIcon: PropTypes.bool,
    bodyPadding: PropTypes.string,
    children: PropTypes.oneOfType([
      PropTypes.arrayOf(PropTypes.node),
      PropTypes.node
    ])
  }

  state = {
    isExpand: this.props.isOpen
  }

  handleExpand = (e) => {
    if (['collapse-head', 'collapse-head-title', 'collapse-head-icon'].includes(e.target.id)) {
      this.setState(prevState => ({
        isExpand: !prevState.isExpand
      }))
    }
  }

  render () {
    const {
      header, isHideIcon, children,
      titleClassName, className, bodyPadding,
      subTitle = '', subButton = {}, isAccordion
    } = this.props
    const { isExpand } = this.state
    return (
      <CollapsableHeader
        className={className}
        isAccordion={isAccordion}
      >
        <Row
          justify='space-between'
          className={`collapsible-header ${isAccordion && 'collapse-head-border'}`}
          id='collapse-head'
          onClick={this.handleExpand}
        >
          <CustomText
            size='14px'
            weight={isAccordion ? 700 : 800}
            color={AgentColorPallette.blackGrey}
            className={titleClassName}
            id='collapse-head-title'
            onClick={(e) => {
              e.stopPropagation()
              this.handleExpand(e)
            }}
          >
            {header}
            {
              subTitle &&
                <CustomText
                  size='10px'
                  color={AgentColorPallette.regular}
                  top='5px'
                >
                  {subTitle}
                </CustomText>
            }
            {
              !isEmpty(subButton) &&
                <Button id={subButton.id} className='sub-button' onClick={() => subButton.onClick()}>
                  {subButton.label}
                </Button>
            }
          </CustomText>
          {
            !isHideIcon &&
              <CustomText
                size='14px'
                color={AgentColorPallette.fontDarkerGrey}
                id='collapse-head-icon'
                onClick={(e) => {
                  e.stopPropagation()
                  this.handleExpand(e)
                }}
              >
                <i className={`fas fa-angle-up ${isExpand ? 'caret-rotate-down' : 'caret-rotate-up'}`} />
              </CustomText>
          }
        </Row>
        <CollapsableBodyStyle open={isExpand} bodyPadding={bodyPadding}>
          {children}
        </CollapsableBodyStyle>
      </CollapsableHeader>
    )
  }
}

export default Collapsible
