import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import get from 'lodash/get'
import { useCallback, useEffect, useRef, useState } from 'react'
import { Row } from '../../commonStyle/index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import { LOCATION_PIN } from '../../images'
import { LANG_STRINGS } from '../../lang'
import { useGetBranchList } from '../../state/globalState/hooks/useGlobalContext'
import Button from '../Button'
import CircularLoader from '../CircularLoader'
import CustomText from '../CustomText'
import FullPageModal from '../FullPageModal'
import InnerInput from '../InnerInput'
import ShowSnackbar from '../ShowNotification'
import { ProviderBranchesStyle } from './index.style'
import PropTypes from 'prop-types'

function ProviderBranches (props) {
  const isShowBranches = useRef(false)
  const { showModal, onCloseModal, onBranchSelect, providerCode } = props
  const [query, setQuery] = useState('')
  const latLng = useRef({
    lat: '',
    lng: ''
  })

  const [{ getBranchListData }, getBranchListRequest] = useGetBranchList()

  const [{ GET_BRANCH_LIST_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [
    {
      GET_BRANCH_LIST_ERROR, getBranchListStatus
    },
    dispatchError
  ] = useErrorContextValue()

  const handleGetBranches = useCallback((searchText = '') => {
    const params = {
      providerCode
    }
    if (searchText || latLng.current.lat) {
      params.query = {}
      if (searchText) {
        params.query.search = searchText
      }
      if (latLng.current.lat) {
        params.query = {
          ...params.query,
          show_distance: true,
          latitude: latLng.current.lat,
          longitude: latLng.current.lng
        }
      }
    }
    getBranchListRequest(params)
  }, [providerCode, getBranchListRequest])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_BRANCH_LIST_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_BRANCH_LIST_LOADER === undefined) {
      const showPosition = (position) => {
        latLng.current = {
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }
        handleGetBranches()
      }
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(showPosition, () => handleGetBranches())
      } else {
        handleGetBranches()
      }
    }
  }, [GET_BRANCH_LIST_LOADER, handleGetBranches])

  useEffect(() => {
    if (getBranchListStatus && getBranchListStatus === 'success') {
      isShowBranches.current = true
      dispatchError(resetError({
        getBranchListStatus: ''
      }))
    } else if (GET_BRANCH_LIST_ERROR && getBranchListStatus) {
      ShowSnackbar.error(getBranchListStatus)
      dispatchError(resetError({
        getBranchListStatus: ''
      }))
    }
  }, [getBranchListStatus, dispatchError,
    GET_BRANCH_LIST_ERROR
  ])

  const handleInputChange = useCallback((e) => {
    setQuery(e.currentTarget.value)
  }, [])

  const handleSearch = useCallback((e) => {
    e.preventDefault()
    handleGetBranches(query)
  }, [handleGetBranches, query])

  const handleSelectBranch = useCallback((branch) => {
    onBranchSelect(branch)
    onCloseModal()
  }, [onBranchSelect, onCloseModal])

  const handleGetBranchDetail = useCallback((branch) => {
    const branchDetail = {}
    if (branch.tags && branch.tags.length > 0) {
      branchDetail.labels = []
      branchDetail.infoTexts = []

      branch.tags.forEach((tag) => {
        switch (tag) {
          case 'HEADQUARTER':
            branchDetail.labels = [
              ...branchDetail.labels,
              {
                text: LANG_STRINGS.headquarter,
                color: AgentColorPallette.warning
              }
            ]
            break
          case 'NEARBY_15':
            branchDetail.labels = [
              ...branchDetail.labels,
              {
                text: LANG_STRINGS.nearbyLocation,
                color: AgentColorPallette.greenDarker
              }
            ]
            branchDetail.infoTexts = [
              ...branchDetail.infoTexts,
              `*${LANG_STRINGS.within15kmOfDeviceLocation}`
            ]
            break
          case 'SAME_CITY':
            branchDetail.labels = [
              ...branchDetail.labels,
              {
                text: LANG_STRINGS.sameCity,
                color: AgentColorPallette.blueGreen
              }
            ]
            branchDetail.infoTexts = [
              ...branchDetail.infoTexts,
              `*${LANG_STRINGS.locationSameCity}`
            ]
            break
          case 'SAME_PROVINCE':
            branchDetail.labels = [
              ...branchDetail.labels,
              {
                text: LANG_STRINGS.sameProvince,
                color: AgentColorPallette.purple
              }
            ]
            branchDetail.infoTexts = [
              ...branchDetail.infoTexts,
              `*${LANG_STRINGS.locationSameProvince}`
            ]
            break
          default:
            break
        }
      })
    }
    return branchDetail
  }, [])

  return (
    <FullPageModal
      onCloseModal={onCloseModal}
      showModal={showModal}
      header={LANG_STRINGS.branchAddressList}
    >
      <CircularLoader className='branch-list-loader' isLoading={GET_BRANCH_LIST_LOADER} bgColor={AgentColorPallette.fontLightGrey}>
        <ProviderBranchesStyle>
          <form className='search-container' onSubmit={handleSearch}>
            <Row align='center'>
              <InnerInput
                name='search'
                className='search-input'
                value={query}
                placeholder={LANG_STRINGS.writeAddrName}
                onChange={handleInputChange}
              />
            </Row>
            <CustomText
              size='13px'
              color={AgentColorPallette.black}
            >
              {LANG_STRINGS.selectBranchAddr}
            </CustomText>
          </form>
          <div>
            {
              isShowBranches.current && getBranchListData && getBranchListData.map((branch, i) => {
                let branchAddress = ''
                const branchDetail = handleGetBranchDetail(branch)
                if (get(branch, 'location.city_name', '')) {
                  branchAddress = `${get(branch, 'location.address')}, ${get(branch, 'location.city_name')} ${get(branch, 'location.postal_code')}, ${get(branch, 'location.province_name')}`
                }
                return (
                  <div className='branch' key={`branch_${i}`}>
                    <CustomText
                      size='18px'
                      color={AgentColorPallette.black}
                      weight={800}
                      bottom='10px'
                    >
                      {branch.name}
                    </CustomText>
                    <Row align='center'>
                      {
                        branchAddress &&
                          <img src={LOCATION_PIN} className='location-pin' alt='' />
                      }
                      <div>
                        <CustomText
                          size='13px'
                          color={AgentColorPallette.black}
                          weight={600}
                        >
                          {branchAddress}
                        </CustomText>
                        {
                          branchDetail.labels && branchDetail.labels.map((label, i) => (
                            <CustomText
                              key={i}
                              size='10px'
                              weight={600}
                              className='branch-label'
                              bgColor={label.color}
                            >
                              {label.text}
                            </CustomText>
                          ))
                        }

                        {
                          branchDetail.infoTexts && branchDetail.infoTexts.map((it, i) => (
                            <CustomText
                              key={`it${i}`}
                              size='10px'
                              color={AgentColorPallette.regular}
                              weight={600}
                              top='10px'
                            >
                              {it}
                            </CustomText>
                          ))
                        }
                      </div>
                    </Row>
                    <div className='text-align-right'>
                      <Button
                        onClick={() => handleSelectBranch(branch)}
                        className='select-btn'
                        color={AgentColorPallette.blackGrey}
                      >
                        {LANG_STRINGS.select}
                      </Button>
                    </div>
                  </div>
                )
              })
            }
          </div>
        </ProviderBranchesStyle>
      </CircularLoader>
      <ShowSnackbar hideOkay />
    </FullPageModal>
  )
}

ProviderBranches.propTypes = {
  providerCode: PropTypes.string,
  showModal: PropTypes.bool,
  onCloseModal: PropTypes.func,
  onBranchSelect: PropTypes.func
}

export default ProviderBranches
