
import { TransactionCardStyle } from './index.style'
import { useCallback, useState } from 'react'
import get from 'lodash/get'
import { AgentColorPallette } from '../../configs/colorPallete'
import CustomText from '../CustomText'
import Button from '../Button'
import { LANG_STRINGS } from '../../lang'
import CollapsibleCard from '../CollapsibleCard'
import { CLOSE_ICON } from '../../images'
import AmountTitle from '../AmountTitle'
import { formatMoney } from '../../helpers/utility'
import { Row } from '../../commonStyle/index.style'
import DiscountModal from '../../containers/Private/Application/components/DiscountModal'

function TransactionCard (props) {
  const [showDiscountModal, setShowDiscountModal] = useState(false)

  const getAmountTitle = useCallback((title, amount, amountColor, prefix, titleColor = AgentColorPallette.fontDarkerGrey, bgColor = AgentColorPallette.white) => {
    if (!amount) return null
    return (
      <AmountTitle
        color={titleColor}
        amountColor={amountColor || AgentColorPallette.black}
        title={title}
        amountPrefix={prefix}
        size='13px'
        amount={formatMoney(amount, 0, '')}
        className='item-padding'
        bgColor={bgColor}
      />
    )
  }, [])

  const handleRemoveDiscount = useCallback(() => {
    props.handleEditDiscount(0)
  }, [props])

  const handleShowModal = () => {
    setShowDiscountModal(true)
  }

  const handleDiscountSubmit = (discount) => {
    props.handleEditDiscount(discount)
    setShowDiscountModal(false)
  }

  const handleCloseDiscountModal = () => {
    setShowDiscountModal(false)
  }

  const getTotalBill = () => {
    return get(props, 'totalBill', 0) - get(props, 'discount', 0)
  }

  const renderDiscount = useCallback((title, amount, amountColor) => {
    let showDiscountEdit = true
    if (props.disableDiscountEdit) {
      showDiscountEdit = false
    }
    if (showDiscountEdit || amount) {
      return (
        <div>
          <Row className='item-padding' align='center' justify='space-between'>
            <CustomText size='13px' color={AgentColorPallette.fontDarkerGrey}>
              {title} {showDiscountEdit && !!amount && <img onClick={handleRemoveDiscount} width='18px' src={CLOSE_ICON} alt='' />}
            </CustomText>
            <CustomText size='13px' textAlign='right' color={amountColor || AgentColorPallette.regular} weight={800}>
              {
                amount ? `- ${formatMoney(amount)}` : (
                  <Button className='add-discount-btn' handleClick={handleShowModal}> {LANG_STRINGS.add} </Button>
                )
              }
            </CustomText>
          </Row>
        </div>
      )
    } else {
      return null
    }
  }, [handleRemoveDiscount, props.disableDiscountEdit])

  return (
    <TransactionCardStyle>
      <CollapsibleCard
        titleClassName='card-title'
        className='collapse-card'
        title={LANG_STRINGS.transactionDetails}
        isOpen
      >
        {getAmountTitle(LANG_STRINGS.basicPremium, props.basicPremium)}
        <hr className='separator' />
        {getAmountTitle(LANG_STRINGS.tax, props.totalTax)}
        {getAmountTitle(LANG_STRINGS.stampDuty, props.stampDuty)}
        {getAmountTitle(LANG_STRINGS.adminFee, props.adminFee)}
        {getAmountTitle(LANG_STRINGS.serviceFee, props.serviceFee)}
        {renderDiscount(LANG_STRINGS.discount, props.discount, AgentColorPallette.errorDark)}
        {getAmountTitle(LANG_STRINGS.totalBill, `${getTotalBill()}`, AgentColorPallette.white, '', AgentColorPallette.white, AgentColorPallette.maroonRed)}
      </CollapsibleCard>
      {
        showDiscountModal && (
          <DiscountModal
            showDiscountModal={showDiscountModal}
            onClose={handleCloseDiscountModal}
            commission={props.commission}
            maxDiscount={props.maxDiscount}
            subTotal={props.subTotal}
            comissionPercent={props.discountPercent}
            onSubmitDiscount={handleDiscountSubmit}
          />
        )
      }
    </TransactionCardStyle>
  )
}

export default TransactionCard
