import { useState } from 'react'
import { DisplayCircleIcon, Row } from '../../commonStyle/index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import { INFO, LOCATION_PIN } from '../../images'
import { LANG_STRINGS } from '../../lang'
import CustomText from '../CustomText'
import ProviderBranches from '../ProviderBranches'
import { ProviderBranchSelectStyle } from './index.style'
import PropTypes from 'prop-types'
import PaymentConfirmationModal from '../../containers/Private/Application/components/PaymentConfirmationModal'

function ProviderBranchSelect(props) {
  const {
    providerCode,
    onBranchSelect,
    selectedBranch,
    hideBoxShadow = false,
  } = props

  const [showBranchesModal, setShowBranchesModal] = useState(false)
  const [showInfoPopup, setShowInfoPopup] = useState(false)

  return (
    <ProviderBranchSelectStyle hideBoxShadow={hideBoxShadow}>
      <Row justify="space-between">
        <Row>
          <img className="location-icon" src={LOCATION_PIN} alt="" />
          <CustomText
            size="16px"
            color={AgentColorPallette.regular}
            weight={800}
          >
            {LANG_STRINGS.policyPublishingOffice}
          </CustomText>
        </Row>
        <DisplayCircleIcon
          width="18px"
          height="18px"
          bgColor={AgentColorPallette.yellow}
          onClick={() => setShowInfoPopup(true)}
        >
          <img src={INFO} alt="INFO" className="info-img" />
        </DisplayCircleIcon>
      </Row>
      <hr className="seprator" />
      <Row justify="space-between" onClick={() => setShowBranchesModal(true)}>
        <div>
          <CustomText size="13px" color={AgentColorPallette.regular}>
            {LANG_STRINGS.addressToBranch}
          </CustomText>
          <CustomText
            size="13px"
            color={AgentColorPallette.regular}
            weight={700}
          >
            {selectedBranch?.name}
          </CustomText>
        </div>
        <div className="up-down">
          <i className="fas fa-angle-down right-caret" />
        </div>
      </Row>
      {showBranchesModal && (
        <ProviderBranches
          providerCode={providerCode}
          showModal={showBranchesModal}
          onBranchSelect={onBranchSelect}
          onCloseModal={() => setShowBranchesModal(false)}
        />
      )}
      <PaymentConfirmationModal
        hideButtons
        confirmText={LANG_STRINGS.policyProcessWithSelectedBranch}
        showModal={showInfoPopup}
        onClose={() => {
          setShowInfoPopup(false)
        }}
      />
    </ProviderBranchSelectStyle>
  )
}

ProviderBranchSelect.propTypes = {
  providerCode: PropTypes.string,
  onBranchSelect: PropTypes.func,
  selectedBranch: PropTypes.object,
  hideBoxShadow: PropTypes.bool,
}

export default ProviderBranchSelect
