import { Component } from 'react'
import PropTypes from 'prop-types'
import { Modal, CustomText, Button } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { PaymentConfirmationStyle } from './index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import CircularLoader from '../../../../../components/CircularLoader'

class PaymentConfirmationModal extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    isLoader: PropTypes.bool,
    confirmText: PropTypes.string,
    onAgree: PropTypes.func,
    onClose: PropTypes.func,
    hideButtons: PropTypes.bool,
  }

  handleAgree = () => {
    this.props.onAgree()
  }

  render() {
    const {
      showModal,
      onClose,
      confirmText,
      isLoader,
      hideButtons = false,
    } = this.props
    return (
      <Modal
        heading={LANG_STRINGS.information}
        isOpen={showModal}
        onClose={onClose}
      >
        <CircularLoader isLoading={isLoader}>
          <PaymentConfirmationStyle>
            <CustomText
              color={AgentColorPallette.black}
              size="14px"
              lineHeight={1.5}
              bottom="20px"
            >
              {confirmText || LANG_STRINGS.onChoosingCommissionStatement}
            </CustomText>
            {!hideButtons && (
              <>
                <Button onClick={this.handleAgree}>
                  {LANG_STRINGS.yesIAgree}
                </Button>
                <div className="payment-cancel" onClick={onClose}>
                  {LANG_STRINGS.cancel}
                </div>
              </>
            )}
          </PaymentConfirmationStyle>
        </CircularLoader>
      </Modal>
    )
  }
}

export default PaymentConfirmationModal
