import { AgentColorPallette } from '../../configs/colorPallete'
import { LANG_STRINGS } from '../../lang'
import CollapsibleCard from '../CollapsibleCard'
import CustomText from '../CustomText'
import { InsuranceInfoCardStyle } from './index.style'
import PropTypes from 'prop-types'
import { useCallback } from 'react'
import isEmpty from 'lodash/isEmpty'
import ProviderBranchSelect from '../ProviderBranchSelect'
import DisclaimerBox from '../DisclaimerBox'

function InsuranceInfoCard (props) {
  const { className = '', tncType, showBranchOption, selectedBranch = {}, onBranchSelect, providerCode, isShowDisclaimer } = props

  const renderTnC = useCallback(() => {
    if (tncType === 'nested') {
      return (
        props.tnc.map((terms, index) => {
          return (
            <>
              <CustomText
                color={AgentColorPallette.black}
                size='13px'
                bottom='20px'
                key={`terms_${index}`}
                lineHeight={1.5}
              >
                {terms.title}
              </CustomText>
              {
                Boolean(terms.type) &&
                  <ol type={terms.type}>
                    {
                      terms.terms.map((term, i) => {
                        return (
                          <li key={i}>
                            <CustomText
                              color={AgentColorPallette.black}
                              size='13px'
                              bottom='20px'
                              key={`termssub_${index}`}
                              lineHeight={1.5}
                            >
                              {term}
                            </CustomText>
                          </li>
                        )
                      })
                    }
                  </ol>
              }
            </>
          )
        })
      )
    } else if (tncType === 'ul-list') {
      return (
        <ul className='m-0'>
          {
            props.tnc.map((term, index) => (
              <li key={`terms_${index}`}>
                <CustomText
                  color={AgentColorPallette.black}
                  size='13px'
                >
                  {term}
                </CustomText>
              </li>
            ))
          }
        </ul>
      )
    } else {
      return (
        <>
          {
            props.tnc.map((terms, index) => (
              <CustomText
                color={AgentColorPallette.black}
                size='13px'
                bottom='20px'
                key={`terms_${index}`}
                lineHeight={1.5}
              >
                {index + 1}. {(typeof terms === 'object') ? terms.description : terms}
              </CustomText>
            ))
          }
        </>
      )
    }
  }, [props.tnc, tncType])

  const renderBenifit = useCallback(() => {
    if (props.benefitType === 'list' && props.benefit) {
      return (
        props.benefit.map((terms, index) => {
          return (
            <>
              {
                terms.title &&
                  <CustomText
                    color={AgentColorPallette.black}
                    size='13px'
                    bottom='10px'
                    key={`terms_${index}`}
                    lineHeight={1.5}
                    weight={800}
                  >
                    {terms.title}
                  </CustomText>
              }
              {
                !isEmpty(terms) &&
                  <ul className='m-0'>
                    {
                      terms.terms.map((term, i) => {
                        return (
                          <li key={i}>
                            <CustomText
                              color={AgentColorPallette.black}
                              size='13px'
                              key={`termssub_${index}`}
                            >
                              {term}
                            </CustomText>
                          </li>
                        )
                      })
                    }
                  </ul>
              }
              {
                terms.description &&
                  <CustomText
                    color={AgentColorPallette.fontDarkerGrey}
                    size='10px'
                    bottom='20px'
                    key={`terms_${index}`}
                    className='pl-35'
                  >
                    {terms.description}
                  </CustomText>
              }
            </>
          )
        })
      )
    } else {
      return (
        <CustomText size='13px' lineHeight={1.5} color={AgentColorPallette.black}>
          {props.benefit}
        </CustomText>
      )
    }
  }, [props.benefit, props.benefitType])

  return (
    <InsuranceInfoCardStyle className={className}>
      <CustomText
        size='15px'
        color={AgentColorPallette.black}
        weight={700}
        className='insur-info'
      >
        {LANG_STRINGS.insuranceInfo}
      </CustomText>

      <hr className='separator' />

      <CollapsibleCard
        title={LANG_STRINGS.benefit}
        titleClassName='card-title'
        className='collapse-card'
      >
        {
          renderBenifit()
        }
      </CollapsibleCard>

      <hr className='separator' />

      <CollapsibleCard
        title={LANG_STRINGS.termsConditions}
        titleClassName='card-title'
        className='collapse-card'
      >
        {
          isShowDisclaimer &&
            <>
              <DisclaimerBox /><br />
            </>
        }
        {
          renderTnC()
        }
      </CollapsibleCard>

      <hr className='separator' />

      <CollapsibleCard
        title={LANG_STRINGS.claimMethos}
        titleClassName='card-title'
        className='collapse-card'
        isOpen
      >
        <CustomText size='13px' lineHeight={1.5} color={AgentColorPallette.black}>
          {props.claims}
        </CustomText>
      </CollapsibleCard>
      {
        showBranchOption &&
          <>
            <hr className='separator' />
            <ProviderBranchSelect
              hideBoxShadow
              selectedBranch={selectedBranch}
              onBranchSelect={onBranchSelect}
              providerCode={providerCode}
            />
          </>
      }
    </InsuranceInfoCardStyle>
  )
}

InsuranceInfoCard.propTypes = {
  claims: PropTypes.string,
  benefit: PropTypes.string,
  tnc: PropTypes.array
}
export default InsuranceInfoCard
